def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v_without_build, build = v.split('+', 1)
        else:
            v_without_build = v
            build = None

        # Split pre-release
        if '-' in v_without_build:
            version_part, prerelease = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_sort_key(prerelease_identifiers):
        if prerelease_identifiers is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release sorts before no pre-release
        key = [0]
        for identifier in prerelease_identifiers:
            if identifier.isdigit():
                # Numeric identifiers sort before non-numeric
                key.append((0, int(identifier)))
            else:
                # Non-numeric identifiers sort by ASCII order
                key.append((1, identifier))

        return tuple(key)

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)
        return (major, minor, patch, prerelease_sort_key(prerelease_identifiers))

    # Stable sort to preserve input order for equal precedence
    return sorted(versions, key=sort_key)

